import {stats} from './engine.js';
import {inferLevel,trainerCap,legalMoves} from './observation.js';
export function evolutionTargets(db,p,count=1,state={}){if(!Number.isInteger(count)||count<1||count>10)return [];let paths=[{p,path:[]}];for(let i=0;i<count;i++){paths=paths.flatMap(x=>(x.p.evolutions||[]).map(id=>db.pokemon.find(q=>q.id===id)).filter(q=>q&&!q.mega&&!x.path.includes(q.id)).filter(q=>{try{legalMoves(db,q,state);return true}catch{return false}}).map(q=>({p:q,path:[...x.path,q.id]})));}const seen=new Set();return paths.filter(x=>!seen.has(x.p.id)&&seen.add(x.p.id));}
const originalFields=['species','iv','observed','shadow','purified','lucky','fast','charged','pvpUse','confirmed','trainer'];
function snapshot(card){return Object.fromEntries(originalFields.map(k=>[k,structuredClone(card[k]??null)]))}
export function applyGrowth(db,card,trainer,action){const p=db.pokemon.find(q=>q.id===card.species);if(!p)throw Error('먼저 포켓몬을 지정해 주세요.');if(!Array.isArray(card.iv)||card.iv.length!==3)throw Error('먼저 IV를 확인해 주세요.');const state={shadow:!!card.shadow,purified:!!card.purified,lucky:!!card.lucky};legalMoves(db,p,state);const inference=inferLevel(db,p,card.iv,trainer,card.observed,state);if(!inference.level)throw Error('CP와 HP를 확인해 현재 레벨을 확정한 뒤 적용해 주세요.');let target=p,level=inference.level,history;
 if(action.kind==='evolve'){const found=evolutionTargets(db,p,action.count,state).find(x=>x.p.id===action.target);if(!found)throw Error('선택한 횟수에 맞는 진화 경로가 없습니다.');target=found.p;history={kind:'evolve',count:action.count,from:p.id,to:target.id,path:found.path,fromLevel:level,toLevel:level};}
 else if(action.kind==='power'){if(!Number.isInteger(action.count)||action.count<1||action.count>100)throw Error('강화 횟수는 1부터 100까지 입력하세요.');level+=action.count*.5;if(level>trainerCap(trainer))throw Error(`현재 트레이너 레벨에서는 포켓몬 레벨 ${trainerCap(trainer)}까지만 강화할 수 있습니다.`);history={kind:'power',count:action.count,from:p.id,to:p.id,fromLevel:inference.level,toLevel:level};}
 else throw Error('지원하지 않는 육성 작업입니다.');
 const allowed=legalMoves(db,target,state),evolving=action.kind==='evolve',fast=evolving?(action.fast||''):(card.fast||''),charged=evolving?(action.charged||''):(card.charged||'');if(fast&&!allowed.fast.includes(fast)||charged&&!allowed.charged.includes(charged))throw Error('진화 후 포켓몬이 보유할 수 없는 기술입니다.');const s=stats(db,target,card.iv,level);return {...card,species:target.id,observed:{cp:s.cp,hp:s.h,calculatedLevel:level},fast,charged,pvpUse:evolving?'':card.pvpUse,trainer,confirmed:true,preview:[],growthBase:card.growthBase||snapshot(card),growthHistory:[...(card.growthHistory||[]),history]};}
export function resetGrowth(card){if(!card.growthBase)return card;const next={...card,...structuredClone(card.growthBase),preview:[]};delete next.growthBase;delete next.growthHistory;return next;}
